// Brand logos embedded as data URIs so they always ship with the code (no separate image files to upload or serve).
// Source: logo files supplied by the owner (PARTFLOW logo suite, SHARP logo). Do not edit by hand.
export const BRAND = {
  logo: 'data:image/webp;base64,',
  wordmark: 'data:image/webp;base64,',
  mark: 'data:image/webp;base64,',
  sharp: 'data:image/webp;base64,',
} as const
export type BrandKind = keyof typeof BRAND
